function buildPayloadForStatus(nextStatus) {
  const today = dayjs().format('YYYY-MM-DD');
  if (nextStatus === 'pending_approval') {
    return {
      quotation_status: 'pending_approval',
      submitted_at: today,
    };
  }
  if (nextStatus === 'approved') {
    return {
      quotation_status: 'approved',
      approved_at: today,
    };
  }
  if (nextStatus === 'sent') {
    return {
      quotation_status: 'sent',
      sent_at: today,
    };
  }
  if (nextStatus === 'accepted') {
    return {
      quotation_status: 'accepted',
      accepted_at: today,
    };
  }
  if (nextStatus === 'rejected') {
    return {
      quotation_status: 'rejected',
      rejected_at: today,
    };
  }
  if (nextStatus === 'converted') {
    return {
      quotation_status: 'converted',
      converted_at: today,
    };
  }
  return {
    quotation_status: nextStatus,
  };
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function updateRecord(resourceName, id, payload) {
  const res = ctx.makeResource('MultiRecordResource');
  res.setResourceName(resourceName);
  return res.update(id, payload, { refresh: false });
}

async function loadRecord(resourceName, id) {
  const res = ctx.makeResource('MultiRecordResource');
  res.setResourceName(resourceName);
  res.setPageSize(1);
  res.setFilter({
    id: {
      $eq: id,
    },
  });
  await res.refresh();
  const rows = res.getData() || [];
  return rows[0] || null;
}

async function loadRecordUntilStatus(resourceName, id, expectedStatus) {
  let latestRecord = null;
  for (const delay of [0, 150, 350, 700]) {
    if (delay) {
      await sleep(delay);
    }
    latestRecord = await loadRecord(resourceName, id);
    if (!expectedStatus || latestRecord?.quotation_status === expectedStatus) {
      return latestRecord;
    }
  }
  return latestRecord;
}

function buildSuccessViewNode(text, pathname) {
  return h(
    Space,
    { size: 8, wrap: true },
    h('span', null, text),
    pathname ? h('a', { href: pathname }, 'View') : null,
  );
}

async function resolveLivePk() {
  // Read fresh on every call — closure-captured popup record goes stale across
  // popup re-opens, causing actions to target the previous quotation.
  const fromView =
    (await ctx.getVar?.('ctx.view.inputArgs.filterByTk')) ??
    (await ctx.getVar?.('ctx.popup.filterByTk'));
  if (fromView != null && fromView !== '') return fromView;
  const livePopup = await ctx.getVar?.('ctx.popup.record');
  if (livePopup?.id != null) return livePopup.id;
  const liveRecord = await ctx.getVar?.('ctx.record');
  return liveRecord?.id ?? null;
}

async function fetchLiveQuotation() {
  const pk = await resolveLivePk();
  if (pk == null) return null;
  const detail = await ctx.api
    .resource('quotations')
    .get({ filterByTk: pk, appends: ['items', 'items.product', 'customer', 'contact'] });
  return detail?.data?.data || null;
}

