const h = React.createElement;

const QuotationLifecycleCard = () => {
  // theme.useToken is reactive under antd's ConfigProvider, so the card
  // re-renders automatically when the user switches themes.
  const { token } = theme.useToken();
  const [recordState, setRecordState] = useState(hostRecord || null);
  const [runningStage, setRunningStage] = useState('');
  const [messageText, setMessageText] = useState('');
  const quotation = recordState || hostRecord || null;
  const currentStatus = String(quotation?.quotation_status || 'draft');
  const currentMeta =
    statusMeta[currentStatus] || { color: 'default', label: currentStatus || '-' };
  const canEditQuotation = EDITABLE_STATUSES.includes(currentStatus);
  const editPath = canEditQuotation
    ? EDIT_QUOTATION_PATH +
      '?filterByTk=' +
      encodeURIComponent(String(quotation?.id || ''))
    : '';

  useEffect(() => {
    let active = true;

    const refreshRecord = async () => {
      // Re-resolve live PK on mount too — hostRecord may already be stale.
      const livePk = await resolveLivePk();
      if (!livePk) return;
      try {
        const nextRecord = await loadRecord('quotations', livePk);
        if (active && nextRecord) {
          setRecordState(nextRecord);
        }
      } catch (error) {
        // Keep the last known local state when background refresh fails.
      }
    };

    refreshRecord();
    return () => {
      active = false;
    };
  }, []);

  const helperText = useMemo(() => {
    if (currentStatus === 'draft') {
      return 'Choose any next stage directly, or keep editing before submission.';
    }
    if (currentStatus === 'pending_approval') {
      return 'Approval in progress. Stage actions are locked here — approve / reject / return must be done from the approver’s interface.';
    }
    if (currentStatus === 'approved') {
      return 'Approved quotations can be sent immediately or moved to another stage when needed.';
    }
    if (currentStatus === 'sent') {
      return 'Customer response is pending. You can move straight to accepted, rejected, or any other stage.';
    }
    if (currentStatus === 'accepted') {
      return 'Accepted quotations can still be repositioned, and conversion remains available in the separate block.';
    }
    if (currentStatus === 'converted') {
      return 'This quotation is already converted. Other actions stay separate from the lifecycle steps.';
    }
    if (currentStatus === 'rejected') {
      return 'Rejected quotations can be reopened by moving back to any working stage.';
    }
    if (currentStatus === 'void') {
      return 'Voided quotations can still be reopened by jumping back to another stage.';
    }
    return 'All lifecycle stages are shown below, and you can jump directly to the one you need.';
  }, [currentStatus]);

  const handleStageChange = async (nextStatus) => {
    // Always resolve the live PK at click time. Closure-captured `quotation.id`
    // can be the previously-opened quotation when the popup framework reuses
    // the JS Block across opens, which caused approvals to be submitted for
    // the wrong record (e.g. clicked QUO-2026050004 → got QUO-2026050080).
    const liveDetail = await fetchLiveQuotation();
    const liveId = liveDetail?.id ?? quotation?.id;
    if (!liveId) {
      ctx.message?.error?.('Quotation record is unavailable.');
      return;
    }
    if (nextStatus === currentStatus) {
      return;
    }
    if (nextStatus === 'converted') {
      ctx.message?.info?.('Use the Convert to order block to complete conversion.');
      return;
    }

    setRunningStage(nextStatus);
    setMessageText('');
    const optimisticRecord = {
      ...(liveDetail || quotation || {}),
      quotation_status: nextStatus,
    };
    setRecordState(optimisticRecord);
    try {
      if (nextStatus === 'pending_approval') {
        // Use <collection>:update?triggerWorkflows=<key> — the ONLY safe path
        // for submitting an EXISTING record for approval (NB approval plugin
        // source, server/ApprovalTrigger.ts:666-704). approvals:create with
        // mode=0 always calls repository.create → builds a duplicate quotation
        // and reparents items.hasMany onto it (server/actions/approvals.ts:125).
        // Workflow head node will set status to pending_approval after this fires.
        await ctx.api.resource('quotations').update({
          filterByTk: liveId,
          values: { quotation_status: 'pending_approval' },
          triggerWorkflows: 'hpsiaojpxno', // Quotation approval workflow.key
        });
      } else {
        await updateRecord('quotations', liveId, buildPayloadForStatus(nextStatus));
      }
      const nextRecord =
        (await loadRecordUntilStatus('quotations', liveId, nextStatus)) ||
        optimisticRecord;
      setRecordState({
        ...optimisticRecord,
        ...nextRecord,
        quotation_status: nextRecord?.quotation_status || nextStatus,
      });
      // Skip ctx.resource.refresh() — it re-executes this script, which
      // re-inits useState(hostRecord). hostRecord = ctx.popup.record can lag
      // the actual server change (popup framework refresh runs out-of-band),
      // causing the visible status to flash back to the old value. The local
      // recordState is already up-to-date from loadRecordUntilStatus, so
      // letting React keep it gives the user a stable display.
      const nextMeta = statusMeta[nextStatus] || { label: nextStatus };
      const successText =
        (nextRecord?.quotation_no || liveDetail?.quotation_no || quotation?.quotation_no || 'Quotation') +
        ' moved to ' +
        nextMeta.label +
        '.';
      setMessageText(successText);
      ctx.notification?.success?.({
        message: t('Quotation updated'),
        description: buildSuccessViewNode(successText, STATUS_TAB_PATHS[nextStatus]),
      });
    } catch (error) {
      const nextError = error?.message || 'Failed to update quotation status.';
      setMessageText(nextError);
      setRecordState(quotation);
      ctx.message?.error?.(nextError);
    } finally {
      setRunningStage('');
    }
  };

  return h(
    Card,
    {
      title: t('Lifecycle actions'),
      style: {
        borderRadius: token.borderRadiusLG,
        border: `1px solid ${token.colorBorderSecondary}`,
        background: `linear-gradient(180deg, ${token.colorBgElevated} 0%, ${token.colorBgContainer} 100%)`,
      },
      extra: h(Tag, { color: currentMeta.color }, currentMeta.label),
    },
    h(
      'div',
      { style: { display: 'grid', gap: 14 } },
      h(
        Descriptions,
        { column: 1, size: 'small', bordered: true },
        h(Descriptions.Item, { label: t('Quotation no') }, quotation?.quotation_no || '-'),
        h(Descriptions.Item, { label: t('Current status') }, currentMeta.label),
        h(
          Descriptions.Item,
          { label: t('How it works') },
          'All lifecycle stages are shown in order below. The current stage is disabled, and you can jump directly to any other stage except conversion, which stays in the dedicated block.',
        ),
      ),
      h(
        Paragraph,
        { type: 'secondary', style: { marginBottom: 0 } },
        helperText,
      ),
      messageText
        ? h(Alert, {
            type:
              messageText.toLowerCase().includes('failed') ||
              messageText.toLowerCase().includes('unavailable')
                ? 'error'
                : 'success',
            showIcon: true,
            message: messageText,
          })
        : null,
      h(
        'div',
        { style: { display: 'grid', gap: 8 } },
        h(
          Text,
          { strong: true, style: { color: token.colorText } },
          'Lifecycle steps',
        ),
        h(
          'div',
          {
            style: {
              display: 'grid',
              gap: 8,
            },
          },
          ...orderedStages.map((stage, index) => {
            const meta = statusMeta[stage.value] || { label: stage.title };
            const isCurrent = stage.value === currentStatus;
            const isBusy = runningStage === stage.value;
            const isConvertOnly = stage.value === 'converted' && currentStatus !== 'converted';
            // When pending_approval: lock everything. Approval can only proceed through
            // the approver's interface (approve / reject / return) — no manual stage shift.
            const isPendingLock = currentStatus === 'pending_approval';
            return h(
              Button,
              {
                key: stage.value,
                type: isCurrent ? 'primary' : 'default',
                danger: stage.value === 'rejected',
                disabled: isCurrent || isConvertOnly || isPendingLock,
                loading: isBusy,
                icon: meta.icon ? h(meta.icon) : null,
                block: true,
                style: {
                  justifyContent: 'flex-start',
                  opacity: 1,
                  fontWeight: isCurrent ? 600 : 500,
                },
                onClick: () => handleStageChange(stage.value),
              },
              (index + 1) + '. ' + stage.title,
            );
          }),
        ),
      ),
      h(
        'div',
        { style: { display: 'grid', gap: 8 } },
        h(
          Text,
          { strong: true, style: { color: token.colorText } },
          'Other actions',
        ),
        h(
          'div',
          {
            style: {
              display: 'grid',
              gap: 8,
            },
          },
          canEditQuotation && quotation?.id
            ? h(
                Button,
                {
                  key: 'editQuotation',
                  type: 'default',
                  icon: h(EditOutlined),
                  onClick: () => ctx.openView('mfcyz6bh50w', {
                    filterByTk: quotation.id,
                    collectionName: 'quotations',
                    dataSourceKey: 'main',
                    popupTemplateUid: 't3kdmv07xab',
                  }),
                  block: true,
                  style: {
                    justifyContent: 'flex-start',
                    color: '#1677ff',
                    borderColor: '#1677ff',
                    fontWeight: 600,
                    boxShadow: '0 0 0 1px rgba(22, 119, 255, 0.08)',
                  },
                },
                'Edit',
              )
            : null,
          h(
            Button,
            {
              key: 'refreshQuotation',
              icon: h(ReloadOutlined),
              block: true,
              style: {
                justifyContent: 'flex-start',
              },
              onClick: () => ctx.resource?.refresh?.(),
            },
            'Refresh',
          ),
        ),
      ),
    ),
  );
};

