try {
  const requests = await loadRows('leave_requests');
  const now = dayjs();
  let value = 0;
  for (const row of requests) {
    if (String(row.leave_type || '') !== 'sick') continue;
    if (!row.start_time) continue;
    const s = dayjs(row.start_time);
    if (!s.isValid() || !s.isSame(now, 'month')) continue;
    const e = dayjs(row.end_time);
    if (!e.isValid()) continue;
    const days = Math.max(e.startOf('day').diff(s.startOf('day'), 'day') + 1, 0);
    value += days;
  }
  ctx.render(<MiniCard label={t("Sick leave days")} value={value} precision={1} suffix="d" note={t("Sick leave days starting this month.")} popupUid={POPUP_UID} />);
} catch (error) {
  ctx.render(
    <div style={{ padding: '12px' }}>
      <Typography.Text type="secondary" style={{ fontSize: 12 }}>
        Sick leave days unavailable.
      </Typography.Text>
    </div>
  );
}

