          marginTop: 2,
          fontSize: 24,
          fontWeight: 600,
          color: valueColor || token.colorText,
          overflow: 'hidden',
          whiteSpace: 'nowrap',
          textOverflow: 'ellipsis',
        }}
      >
        {prefix ?? ''}{formatNumber(value, precision)}{suffix ?? ''}
