function formatDate(value) {
  if (!value) return t('TBD');
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return month + '/' + day;
}

function sortByDate(items) {
  return [...items].sort((left, right) => {
    const leftValue = left.planned_finish_date || left.actual_finish_date || '';
    const rightValue = right.planned_finish_date || right.actual_finish_date || '';
    return String(leftValue).localeCompare(String(rightValue));
  });
}

function getStatusMeta(status) {
  if (status === 'completed') {
    return {
      label: t('Completed'),
      accent: '#16a34a',
      soft: '#dcfce7',
      border: '#86efac',
      track: 'linear-gradient(90deg, #22c55e 0%, #16a34a 100%)',
    };
  }
  if (status === 'in_progress') {
    return {
      label: t('In Progress'),
      accent: '#2563eb',
      soft: '#dbeafe',
      border: '#93c5fd',
      track: 'linear-gradient(90deg, #60a5fa 0%, #2563eb 100%)',
    };
  }
  return {
    label: t('Not Started'),
    accent: '#64748b',
    soft: '#f1f5f9',
    border: '#cbd5e1',
    track: 'linear-gradient(90deg, #cbd5e1 0%, #94a3b8 100%)',
  };
}

