const t = (k, o) => ctx.t(k, { ns: 'nb_demo', ...(o || {}) });
const { React, antd } = ctx.libs;
const { useEffect, useMemo, useState } = React;
const { Card, Col, Descriptions, Empty, Row, Space, Spin, Tag, Typography, theme } = antd;
const { Paragraph, Text, Title } = Typography;

const h = React.createElement;

function toNumber(value) {
  if (value === null || value === undefined || value === '') {
    return 0;
  }
  const next = Number(value);
  return Number.isFinite(next) ? next : 0;
}

function round2(value) {
  return Math.round((toNumber(value) + Number.EPSILON) * 100) / 100;
}

function formatMoney(currencyCode, value) {
  try {
    return new Intl.NumberFormat('zh-CN', {
      style: 'currency',
      currency: currencyCode || 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(toNumber(value));
  } catch (error) {
    return round2(value).toFixed(2);
  }
}

function buildParameterLabel(parameter) {
  if (parameter?.parameter_name && parameter?.parameter_code) {
    return parameter.parameter_name + ' (' + parameter.parameter_code + ')';
  }
  return parameter?.parameter_name || parameter?.parameter_code || t('Parameter');
}

function formatAdjustmentModeLabel(mode) {
  const labels = {
    none: t('No adjustment'),
    fixed_plus: t('Fixed surcharge'),
    fixed_minus: t('Fixed discount'),
    ratio_plus: t('Ratio surcharge'),
    ratio_minus: t('Ratio discount'),
    replace_base: t('Replace base price'),
  };
  return labels[mode] || mode || t('No adjustment');
}

function formatOrderStatus(status) {
  const labels = {
    draft: t('Draft'),
    pending_confirmation: t('Pending confirmation'),
    confirmed: t('Confirmed'),
    delivering: t('Delivering'),
    completed: t('Completed'),
    cancelled: t('Cancelled'),
    void: t('Void'),
  };
  return labels[status] || status || '-';
}

function formatPaymentStatus(status) {
  const labels = {
    unpaid: t('Unpaid'),
    partial: t('Partially paid'),
    paid: t('Paid'),
    overdue: t('Overdue'),
  };
  return labels[status] || status || '-';
}

function formatDeliveryStatus(status) {
  const labels = {
    not_started: t('Not started'),
    in_progress: t('In progress'),
    delivered: t('Delivered'),
    partial: t('Partially delivered'),
  };
  return labels[status] || status || '-';
}

function formatInvoiceStatus(status) {
  const labels = {
    not_invoiced: t('Not invoiced'),
    partial: t('Partially invoiced'),
    invoiced: t('Invoiced'),
  };
  return labels[status] || status || '-';
}

async function listRecords(resourceName, options = {}) {
  const res = ctx.makeResource('MultiRecordResource');
  res.setResourceName(resourceName);
  res.setPageSize(options.pageSize || 200);
  if (options.fields) res.setFields(options.fields);
  if (options.filter) res.setFilter(options.filter);
  if (options.sort) res.setSort(options.sort);
  if (options.appends) res.setAppends(options.appends);
  await res.refresh();
  return res.getData() || [];
}

