async function submitOrderApproval(orderId) {
  // Use <collection>:update?triggerWorkflows=<key> — the ONLY safe path for
  // submitting an EXISTING record (NB approval plugin source: ApprovalTrigger
  // .ts:666-704). approvals:create with mode=0 always calls repository.create
  // → builds a duplicate order and reparents items.hasMany onto it
  // (server/actions/approvals.ts:125). Workflow head node sets pending_confirmation.
  await ctx.api.resource('orders').update({
    filterByTk: orderId,
    values: { order_status: 'pending_confirmation' },
    triggerWorkflows: ORDER_APPROVAL_WORKFLOW_KEY,
  });
}

async function loadRecord(resourceName, id) {
  const res = ctx.makeResource('MultiRecordResource');
  res.setResourceName(resourceName);
  res.setPageSize(1);
  res.setFields([
    'id',
    'order_no',
    'order_status',
    'payment_status',
    'invoice_status',
    'delivery_status',
  ]);
  res.setFilter({
    id: {
      $eq: id,
    },
  });
  await res.refresh();
  const rows = res.getData() || [];
  return rows[0] || null;
}

async function loadRecordUntilStatus(resourceName, id, expectedStatus) {
  let latestRecord = null;
  for (const delay of [0, 150, 350, 700]) {
    if (delay) {
      await sleep(delay);
    }
    latestRecord = await loadRecord(resourceName, id);
    if (!expectedStatus || latestRecord?.order_status === expectedStatus) {
      return latestRecord;
    }
  }
  return latestRecord;
}

function buildSuccessViewNode(text, pathname) {
