const OrderWorkflowCard = () => {
  // theme.useToken is reactive under antd's ConfigProvider, so the card
  // re-renders automatically when the user switches themes.
  const { token } = theme.useToken();
  const [recordState, setRecordState] = useState(hostRecord || null);
  const [actionLoading, setActionLoading] = useState('');
  const [messageText, setMessageText] = useState('');
  const detail = recordState || hostRecord || null;
  const currentStatus = detail?.order_status || 'draft';
  const currentMeta =
    statusMeta[currentStatus] || { color: 'default', label: currentStatus || '-' };
  const isPendingLock = currentStatus === 'pending_confirmation';

  useEffect(() => {
    let active = true;

    const refreshRecord = async () => {
      if (!hostRecord?.id) {
        return;
      }
      try {
        const nextRecord = await loadRecord('orders', hostRecord.id);
        if (active && nextRecord) {
          setRecordState((prev) => ({ ...(prev || hostRecord || {}), ...nextRecord }));
        }
      } catch (error) {
        // Keep the last known local state when background refresh fails.
      }
    };

    refreshRecord();
    return () => {
      active = false;
    };
  }, []);

  const helperText = useMemo(() => {
    if (currentStatus === 'draft') {
      return t('Draft orders can move forward for confirmation, or jump directly to any later stage if the business already progressed.');
    }
    if (currentStatus === 'pending_confirmation') {
      return t('Order is under approval. All lifecycle actions are locked until the approver decides — once approved it moves to Confirmed, returned drops back to Draft, rejected becomes Cancelled.');
    }
    if (currentStatus === 'confirmed') {
      return t('Confirmed orders can start delivery immediately, but you can also jump to another stage when needed.');
    }
    if (currentStatus === 'delivering') {
      return t('Delivering orders can complete, pause through another status, or move back if the process resets.');
    }
    if (currentStatus === 'completed') {
      return t('Completed orders can still be repositioned if the downstream process needs correction.');
    }
    if (currentStatus === 'cancelled') {
      return t('Cancelled orders can be reopened by jumping back to any working stage.');
    }
    if (currentStatus === 'void') {
      return t('Void orders can still be reopened by jumping back to an active stage.');
    }
    return t('All workflow stages are shown below, and you can jump directly to the one you need.');
  }, [currentStatus]);

  const runTransition = async (nextStatus) => {
    if (!detail?.id) {
      ctx.message?.error?.(t('Order record is unavailable.'));
      return;
    }

    if (nextStatus === currentStatus) {
      return;
    }

    const nextMeta = statusMeta[nextStatus] || { label: nextStatus };
    const successText =
      (detail?.order_no || t('Order')) + t(' moved to ') + nextMeta.label + '.';

    setActionLoading(nextStatus);
    setMessageText('');
    const optimisticRecord = {
      ...(detail || {}),
      ...buildPayloadForStatus(nextStatus, detail),
    };
    setRecordState(optimisticRecord);
    try {
      if (nextStatus === 'pending_confirmation') {
        await submitOrderApproval(detail.id);
      } else {
        await updateRecord('orders', detail.id, buildPayloadForStatus(nextStatus, detail));
      }
      const nextRecord =
        (await loadRecordUntilStatus('orders', detail.id, nextStatus)) ||
        optimisticRecord;
      setRecordState({
        ...optimisticRecord,
        ...nextRecord,
        order_status: nextRecord?.order_status || nextStatus,
      });
      // Skip ctx.resource.refresh() — it re-executes this script, which
      // re-inits useState(hostRecord). hostRecord = ctx.popup.record lags
      // the actual server change (popup framework refresh is out-of-band),
      // causing the visible status to flash back. local recordState is
      // already up-to-date from loadRecordUntilStatus.
      setMessageText(successText);
      ctx.notification?.success?.({
        message: t('Order updated'),
        description: buildSuccessViewNode(successText, STATUS_TAB_PATHS[nextStatus]),
      });
    } catch (error) {
      const nextError = error?.message || t('Failed to update order status.');
      setMessageText(nextError);
      setRecordState(detail);
      ctx.message?.error?.(nextError);
    } finally {
      setActionLoading('');
    }
  };

  return h(
    Card,
    {
      title: t('Order workflow'),
      style: {
        borderRadius: token.borderRadiusLG,
        border: `1px solid ${token.colorBorderSecondary}`,
        background: `linear-gradient(180deg, ${token.colorBgElevated} 0%, ${token.colorBgContainer} 100%)`,
      },
      extra: h(Tag, { color: currentMeta.color }, currentMeta.label),
    },
    h(
      'div',
      { style: { display: 'grid', gap: 14 } },
      h(
        Descriptions,
        { column: 1, size: 'small', bordered: true },
        h(Descriptions.Item, { label: t('Order no') }, detail?.order_no || '-'),
        h(Descriptions.Item, { label: t('Current stage') }, formatOrderStatus(currentStatus)),
        h(Descriptions.Item, { label: t('Payment') }, formatPaymentStatus(detail?.payment_status)),
        h(Descriptions.Item, { label: t('Invoice') }, formatInvoiceStatus(detail?.invoice_status)),
        h(Descriptions.Item, { label: t('Delivery') }, formatDeliveryStatus(detail?.delivery_status)),
        h(
          Descriptions.Item,
          { label: t('How it works') },
          t('All workflow stages are listed below in order. The current stage is highlighted and disabled, and the other stages can be clicked directly.'),
        ),
      ),
      h(Paragraph, { type: 'secondary', style: { marginBottom: 0 } }, helperText),
      messageText
        ? h(Alert, {
            type:
              messageText.toLowerCase().includes('failed') ||
              messageText.toLowerCase().includes('unavailable')
                ? 'error'
                : 'success',
            showIcon: true,
            message: messageText,
          })
        : null,
      h(
        Text,
        { strong: true, style: { color: token.colorText } },
        t('Lifecycle steps'),
      ),
      h(
        'div',
        {
          style: {
            display: 'grid',
            gap: 8,
          },
        },
        ...orderedStages.map((stage, index) => {
          const meta = statusMeta[stage.value] || { label: stage.title };
          const isCurrent = stage.value === currentStatus;
          return h(
            Button,
            {
              key: stage.value,
              type: isCurrent ? 'primary' : 'default',
              danger: stage.value === 'cancelled',
              disabled: isCurrent || isPendingLock,
              loading: actionLoading === stage.value,
              icon: meta.icon ? h(meta.icon) : null,
              block: true,
              style: {
                justifyContent: 'flex-start',
                opacity: 1,
                fontWeight: isCurrent ? 600 : 500,
              },
              onClick: () => runTransition(stage.value),
            },
            (index + 1) + '. ' + stage.title,
          );
        }),
      ),
      h(
        Text,
        { strong: true, style: { color: token.colorText } },
        t('Other actions'),
      ),
      h(
        Button,
        {
          icon: h(ReloadOutlined),
          block: true,
          style: {
            justifyContent: 'flex-start',
          },
          onClick: async () => {
            if (!detail?.id) {
              return;
            }
            const nextRecord = await loadRecord('orders', detail.id);
            if (nextRecord) {
              setRecordState((prev) => ({ ...(prev || detail || {}), ...nextRecord }));
            }
            await ctx.resource?.refresh?.();
          },
        },
        t('Refresh'),
      ),
    ),
  );
};

