function toNumber(value) {
  if (value === null || value === undefined || value === '') {
    return 0;
  }
  const next = Number(value);
  return Number.isFinite(next) ? next : 0;
}

function round2(value) {
  return Math.round((toNumber(value) + Number.EPSILON) * 100) / 100;
}

function calcParameterImpact(parameter, basePrice) {
  const mode = parameter?.price_adjustment_mode || 'none';
  const value = toNumber(parameter?.price_adjustment_value);
  const normalizedBase = toNumber(basePrice);

  if (mode === 'fixed_plus') return round2(value);
  if (mode === 'fixed_minus') return round2(-value);
  if (mode === 'ratio_plus') return round2(normalizedBase * (value / 100));
  if (mode === 'ratio_minus') return round2(-normalizedBase * (value / 100));
  if (mode === 'replace_base') return round2(value - normalizedBase);
  return 0;
}

function calcAccessorySubtotal(accessory) {
  return round2(
    Math.max(0, toNumber(accessory?.quantity_value)) * Math.max(0, toNumber(accessory?.unit_price)),
  );
}

function calcParameterSurcharge(item) {
  return round2(
    (item?.parameters || []).reduce(
      (sum, parameter) => sum + calcParameterImpact(parameter, item?.base_unit_price),
      0,
    ),
  );
}

function formatMoney(currencyCode, value) {
  try {
    return new Intl.NumberFormat('zh-CN', {
      style: 'currency',
      currency: currencyCode || 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(toNumber(value));
  } catch (error) {
    return round2(value).toFixed(2);
  }
}

function buildParameterLabel(parameter) {
  if (parameter?.parameter_name && parameter?.parameter_code) {
    return parameter.parameter_name + ' (' + parameter.parameter_code + ')';
  }
  return parameter?.parameter_name || parameter?.parameter_code || 'Parameter';
}

function formatAdjustmentModeLabel(mode) {
  const labels = {
    none: 'No adjustment',
    fixed_plus: 'Fixed surcharge',
    fixed_minus: 'Fixed discount',
    ratio_plus: 'Ratio surcharge',
    ratio_minus: 'Ratio discount',
    replace_base: 'Replace base price',
  };
  return labels[mode] || mode || 'No adjustment';
}

