const QuotationDetailPreview = () => {
  // theme.useToken is reactive under antd's ConfigProvider, so the card
  // re-renders automatically when the user switches themes.
  const { token } = theme.useToken();
  const quotation = hostRecord;
  const previewPrintRef = useRef(null);
  const [loading, setLoading] = useState(true);
  const [quotationDetail, setQuotationDetail] = useState(hostRecord);
  const [items, setItems] = useState([]);
  const [errorText, setErrorText] = useState('');

  useEffect(() => {
    const element = ctx.element;
    const ownerDocumentKey = 'owner' + 'Document';
    const doc = element ? element[ownerDocumentKey] : null;
    const head = doc?.head;
    if (!doc || !head) {
      return undefined;
    }

    const style = doc.createElement('style');
    style.setAttribute('data-quotation-print-style', 'true');
    style.textContent = `
