  useEffect(() => {
    let active = true;

    const bootstrap = async () => {
      if (!quotation?.id) {
        setErrorText('Quotation record is unavailable.');
        setLoading(false);
        return;
      }

      setLoading(true);
      setErrorText('');
      try {
        const quotationRows = await listRecords('quotations', {
          fields: [
            'id',
            'quotation_no',
            'quotation_date',
            'valid_until',
            'quotation_status',
            'currency_code',
            'subtotal_amount',
            'discount_amount',
            'tax_rate',
            'tax_amount',
            'shipping_fee',
            'other_fee',
            'total_amount',
            'payment_terms',
            'delivery_cycle',
            'warranty_terms',
            'special_terms',
            'remark',
            'owner_id',
            'customer_id',
            'contact_id',
            'contact_email_snapshot',
            'contact_phone_snapshot',
            'customer_address_snapshot',
          ],
          appends: ['customer', 'contact', 'owner'],
          filter: {
            id: {
              $eq: quotation.id,
            },
          },
        });

        const itemRows = await listRecords('quotation_items', {
          fields: [
            'id',
            'product_name_snapshot',
            'product_no_snapshot',
            'product_type_snapshot',
            'pricing_mode_snapshot',
            'quantity_value',
            'unit_name',
