  const [filterKey, setFilterKey] = useState('all');
  const [page, setPage] = useState(1);
  // theme.useToken is reactive under antd's ConfigProvider, so the card
  // re-renders automatically when the user switches themes.
  const { token } = theme.useToken();

  const filteredItems = useMemo(() => {
    if (filterKey === 'urgent') {
      return items.filter((row) => ['urgent', 'high'].includes(String(row.priority_level || '')));
    }
    if (filterKey === 'mine') {
      return items.filter((row) => String(row.owner_id || row.owner?.id || '') === String(currentUser?.id || ''));
    }
    return items;
  }, [items, filterKey]);

  useEffect(() => {
    setPage(1);
  }, [filterKey]);

  const visibleItems = useMemo(() => filteredItems.slice(0, page * PAGE_SIZE), [filteredItems, page]);
  const hasMore = visibleItems.length < filteredItems.length;

  // Surface colors are derived from antd design tokens so the card adapts to
  // light, dark, and compact-dark themes instead of always rendering white.
  // - colorBgContainer / colorErrorBg: card surface with a subtle red tint
  // - colorErrorBorder: theme-aware border for the "overdue" emphasis
  // - boxShadowCard: antd's standard elevated card shadow
  const cardStyle = {
    width: '100%',
    textAlign: 'left',
    border: `1px solid ${token.colorErrorBorder}`,
    background: `linear-gradient(180deg, ${token.colorBgContainer} 0%, ${token.colorErrorBg} 100%)`,
    borderRadius: token.borderRadiusLG,
    padding: '14px 16px',
    cursor: 'pointer',
    boxShadow: token.boxShadowCard,
  };

  return (
    <>
      <div style={{ padding: '6px 10px 12px' }}>
        <Space size={12} style={{ justifyContent: 'space-between', width: '100%', alignItems: 'flex-start' }}>
          <div>
            <Typography.Text strong>{t('Overdue tickets')}</Typography.Text>
            <Typography.Text type="secondary" style={{ display: 'block', fontSize: 12, marginTop: 2 }}>
              {filteredItems.length ? t('{{count}} open tickets need immediate attention', { count: filteredItems.length }) : t('No tickets match the current filter.')}
            </Typography.Text>
          </div>
          <Tag color={filteredItems.length ? 'red' : 'green'}>{filteredItems.length}</Tag>
        </Space>
        <div style={{ marginTop: 12 }}>
          <Segmented
            size="small"
            value={filterKey}
            onChange={setFilterKey}
            options={[
              { label: 'All', value: 'all' },
              { label: t('Urgent only'), value: 'urgent' },
              { label: t('Assigned to me'), value: 'mine' },
            ]}
          />
        </div>
      </div>

      {visibleItems.length ? (
        <>
          <List
            dataSource={visibleItems}
            split={false}
            renderItem={(row) => (
              <List.Item style={{ padding: '0 8px 10px' }}>
                <button
                  type="button"
                  onClick={() => openDetails(row)}
                  style={cardStyle}
                >
                  <Space size={12} style={{ display: 'flex', justifyContent: 'space-between', width: '100%', alignItems: 'flex-start' }}>
                    <div style={{ minWidth: 0, flex: 1 }}>
                      <Typography.Text strong ellipsis style={{ display: 'block', fontSize: 14 }}>
                        {row.ticket_title || row.ticket_no || ('#' + row.id)}
                      </Typography.Text>
                      <Typography.Text type="secondary" ellipsis style={{ display: 'block', marginTop: 4, fontSize: 12 }}>
                        {(row.customer?.customer_name || t('Unknown customer'))}
                        {row.owner?.nickname ? (' · ' + row.owner.nickname) : ''}
                      </Typography.Text>
                      <Space size={[6, 6]} wrap style={{ marginTop: 10 }}>
                        <Tag color={PRIORITY_COLOR[row.priority_level] || 'default'}>{titleCase(row.priority_level)}</Tag>
                        <Tag color={STATUS_COLOR[row.ticket_status] || 'default'}>{titleCase(row.ticket_status)}</Tag>
                        <Tag color="error">{daysLate(row.planned_resolve_at)}d late</Tag>
                        <Tag>{t('Due')}: {formatDate(row.planned_resolve_at)}</Tag>
                      </Space>
                    </div>
                    <Button type="link" size="small" danger onClick={(event) => { event.stopPropagation(); openDetails(row); }}>
                      {t('View')}
                    </Button>
                  </Space>
                </button>
              </List.Item>
            )}
          />
          {hasMore ? (
            <div style={{ padding: '0 8px 10px' }}>
              <Button block onClick={() => setPage((current) => current + 1)}>
                {t('Load more')}
              </Button>
            </div>
          ) : null}
        </>
      ) : (
        <div style={{ padding: '18px 8px 10px' }}>
          <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description={t('No overdue tickets')} />
        </div>
      )}
    </>
  );
}

