                {t('Load more')}
              </Button>
            </div>
          ) : null}
        </>
      ) : (
        <div style={{ padding: '18px 8px 10px' }}>
          <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description={t('No maintenance records')} />
        </div>
      )}
    </>
  );
}

