const t = (k, o) => ctx.t(k, { ns: 'nb_demo', ...(o || {}) });
const { React, antd } = ctx.libs;
const { useMemo, useState } = React;
const { Alert, Button, Card, Descriptions, Space, Tag, Typography, theme } = antd;
const { Paragraph, Text } = Typography;

const stageMeta = {
  new: { color: 'blue', label: t('New lead') },
  contacted: { color: 'cyan', label: 'Contacted' },
  qualified: { color: 'geekblue', label: t('Requirements confirmed') },
  proposal: { color: 'purple', label: t('Proposal or quotation') },
  negotiation: { color: 'orange', label: 'Negotiation' },
  won: { color: 'green', label: 'Won' },
  lost: { color: 'red', label: 'Lost' },
};

const actionCatalog = [
  { key: 'toContacted', title: t('Move to Contacted'), nextStage: 'contacted', allowed: ['new', 'lost'] },
  { key: 'toQualified', title: t('Confirm requirements'), nextStage: 'qualified', allowed: ['contacted'] },
  { key: 'toProposal', title: t('Prepare proposal'), nextStage: 'proposal', allowed: ['qualified', 'lost'] },
  { key: 'toNegotiation', title: t('Enter negotiation'), nextStage: 'negotiation', allowed: ['proposal'] },
  { key: 'toWon', title: t('Mark as won'), nextStage: 'won', allowed: ['negotiation'] },
  { key: 'toLost', title: t('Mark as lost'), nextStage: 'lost', allowed: ['new', 'contacted', 'qualified', 'proposal', 'negotiation'] },
  { key: 'reopenFromWon', title: t('Reopen to negotiation'), nextStage: 'negotiation', allowed: ['won'] },
  { key: 'stepBackToNew', title: t('Back to new lead'), nextStage: 'new', allowed: ['contacted'] },
  { key: 'stepBackToContacted', title: t('Back to contacted'), nextStage: 'contacted', allowed: ['qualified'] },
  { key: 'stepBackToQualified', title: t('Back to requirements confirmed'), nextStage: 'qualified', allowed: ['proposal'] },
  { key: 'stepBackToProposal', title: t('Back to proposal'), nextStage: 'proposal', allowed: ['negotiation'] },
];

async function updateRecord(resourceName, id, payload) {
  const res = ctx.makeResource('MultiRecordResource');
  res.setResourceName(resourceName);
  return res.update(id, payload, { refresh: false });
}

const hostRecord =
  (await ctx.getVar?.('ctx.popup.record')) ||
  (await ctx.getVar?.('ctx.record')) ||
  null;

const h = React.createElement;

const LeadLifecycleCard = () => {
  // theme.useToken is reactive under antd's ConfigProvider, so the card
  // re-renders automatically when the user switches themes.
  const { token } = theme.useToken();
  const [currentStage, setCurrentStage] = useState(String(hostRecord?.stage || 'new'));
  const [runningKey, setRunningKey] = useState('');
  const [messageText, setMessageText] = useState('');

  const currentMeta = stageMeta[currentStage] || { color: 'default', label: currentStage || '-' };
  const nextActions = useMemo(
    () => actionCatalog.filter((action) => action.allowed.includes(currentStage)),
    [currentStage],
  );

  const helperText = useMemo(() => {
    if (currentStage === 'new') return 'Reach out first, then move the lead into contacted or close it as lost.';
    if (currentStage === 'contacted') return 'After first contact, either confirm requirements or return it to a fresh lead.';
    if (currentStage === 'qualified') return 'Once requirements are clear, the lead is ready for a proposal.';
    if (currentStage === 'proposal') return 'Proposal sent. Move it into negotiation when active discussion starts.';
    if (currentStage === 'negotiation') return 'Negotiation can end in a win, or the lead can be marked lost.';
    if (currentStage === 'won') return 'This lead is won. Reopen it only if the deal needs to go back into negotiation.';
    if (currentStage === 'lost') return 'Lost leads can be reopened when the conversation resumes.';
    return 'Use the actions below to move this lead through the lifecycle.';
  }, [currentStage]);

  const handleAction = async (action) => {
    if (!hostRecord?.id) {
      ctx.message?.error?.('Lead record is unavailable.');
      return;
    }

    setRunningKey(action.key);
    setMessageText('');
    try {
      await updateRecord('leads', hostRecord.id, { stage: action.nextStage });
      setCurrentStage(action.nextStage);
      await ctx.resource?.refresh?.();
      const nextMeta = stageMeta[action.nextStage] || { label: action.nextStage };
      const successText = (hostRecord?.lead_name || 'Lead') + ' moved to ' + nextMeta.label + '.';
      setMessageText(successText);
      ctx.notification?.success?.({
        message: t('Lead updated'),
        description: successText,
      });
    } catch (error) {
      const nextError = error?.message || 'Failed to update lead stage.';
      setMessageText(nextError);
      ctx.message?.error?.(nextError);
    } finally {
      setRunningKey('');
    }
  };

  ctx.render(
    h(
      Card,
      {
        title: t('Lifecycle actions'),
        style: {
          borderRadius: token.borderRadiusLG,
          border: `1px solid ${token.colorBorderSecondary}`,
          background: `linear-gradient(180deg, ${token.colorBgContainer} 0%, ${token.colorBgElevated} 100%)`,
        },
        extra: h(Tag, { color: currentMeta.color }, currentMeta.label),
      },
      h(
        'div',
        { style: { display: 'grid', gap: 14 } },
        h(
          Descriptions,
          { column: 1, size: 'small', bordered: true },
          h(Descriptions.Item, { label: 'Lead' }, hostRecord?.lead_name || '-'),
          h(Descriptions.Item, { label: t('Current stage') }, currentMeta.label),
          h(Descriptions.Item, { label: t('Recommended next step') }, helperText),
        ),
        h(
          Paragraph,
          { type: 'secondary', style: { marginBottom: 0 } },
          'Use these actions to move the lead through qualification, proposal, negotiation, and outcome tracking.',
        ),
        messageText
          ? h(Alert, {
              type: messageText.toLowerCase().includes('failed') || messageText.toLowerCase().includes('unavailable') ? 'error' : 'success',
              showIcon: true,
              message: messageText,
            })
          : null,
        nextActions.length
          ? h(
              Space,
              { wrap: true, size: 10 },
              ...nextActions.map((action) =>
                h(
                  Button,
                  {
                    key: action.key,
                    type: ['toContacted', 'toQualified', 'toProposal', 'toNegotiation', 'toWon'].includes(action.key) ? 'primary' : 'default',
                    danger: action.nextStage === 'lost',
                    loading: runningKey === action.key,
                    onClick: () => handleAction(action),
                  },
                  action.title,
                ),
              ),
              h(
                Button,
                {
                  onClick: () => ctx.resource?.refresh?.(),
                },
                'Refresh',
              ),
            )
          : h(Text, { type: 'secondary' }, 'No lifecycle actions are available for the current stage.'),
      ),
    ),
  );
};

ctx.render(h(LeadLifecycleCard));

