const t = (k, o) => ctx.t(k, { ns: 'nb_demo', ...(o || {}) });
const { React, antd } = ctx.libs;
const { useEffect, useMemo, useState } = React;
const { Alert, Button, Card, Descriptions, Space, Tag, Typography, theme } = antd;
const { Paragraph, Text } = Typography;

const stageMeta = {
  new: { color: "blue", label: t("New lead") },
  contacted: { color: "cyan", label: "Contacted" },
  qualified: { color: "geekblue", label: t("Requirements confirmed") },
  proposal: { color: "purple", label: t("Proposal or quotation") },
  negotiation: { color: "orange", label: "Negotiation" },
  won: { color: "green", label: "Won" },
  lost: { color: "red", label: "Lost" },
};

const orderedStages = [
  { value: "new", title: t("New lead") },
  { value: "contacted", title: "Contacted" },
  { value: "qualified", title: t("Requirements confirmed") },
  { value: "proposal", title: t("Proposal or quotation") },
  { value: "negotiation", title: "Negotiation" },
  { value: "won", title: "Won" },
  { value: "lost", title: "Lost" },
];

const arrowStyle = {
  color: "#98a2b3",
  fontSize: 16,
  lineHeight: "32px",
  paddingInline: 2,
};

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function updateRecord(resourceName, id, payload) {
  const res = ctx.makeResource("MultiRecordResource");
  res.setResourceName(resourceName);
  return res.update(id, payload, { refresh: false });
}

async function loadRecord(resourceName, id) {
  const res = ctx.makeResource("MultiRecordResource");
  res.setResourceName(resourceName);
  res.setPageSize(1);
  res.setFilter({
    id: {
      $eq: id,
    },
  });
  await res.refresh();
  const rows = res.getData() || [];
  return rows[0] || null;
}

async function loadRecordUntilStage(resourceName, id, expectedStage) {
  let latestRecord = null;
  for (const delay of [0, 150, 350, 700]) {
    if (delay) {
      await sleep(delay);
    }
    latestRecord = await loadRecord(resourceName, id);
    if (!expectedStage || latestRecord?.stage === expectedStage) {
      return latestRecord;
    }
  }
  return latestRecord;
}

async function refreshBoundResources() {
  const tasks = [ctx.resource?.refresh?.()].filter(Boolean);
  if (!tasks.length) {
    return;
  }
  await Promise.allSettled(tasks);
}

const hostRecord =
  (await ctx.getVar?.("ctx.popup.record")) ||
  (await ctx.getVar?.("ctx.record")) ||
  null;

const h = React.createElement;

const LeadLifecycleCard = () => {
  // theme.useToken is reactive under antd's ConfigProvider, so the card
  // re-renders automatically when the user switches themes.
  const { token } = theme.useToken();
  const [recordState, setRecordState] = useState(hostRecord || null);
  const [runningStage, setRunningStage] = useState("");
  const [messageText, setMessageText] = useState("");
  const currentStage = String(recordState?.stage || hostRecord?.stage || "new");

  const currentMeta =
    stageMeta[currentStage] || { color: "default", label: currentStage || "-" };

  useEffect(() => {
    let active = true;

    const refreshRecord = async () => {
      if (!hostRecord?.id) {
        return;
      }
      try {
        const nextRecord = await loadRecord("leads", hostRecord.id);
        if (active && nextRecord) {
          setRecordState(nextRecord);
        }
      } catch (error) {
        // Keep the last known local state when background refresh fails.
      }
    };

    refreshRecord();
    return () => {
      active = false;
    };
  }, []);

  const helperText = useMemo(() => {
    if (currentStage === "new") {
      return "Start here, then move the lead forward whenever contact begins.";
    }
    if (currentStage === "contacted") {
      return "You can jump ahead once requirements are clear, or move it back if needed.";
    }
    if (currentStage === "qualified") {
      return "Requirements are confirmed. Move straight to proposal or any later outcome when appropriate.";
    }
    if (currentStage === "proposal") {
      return "The proposal stage can jump forward to negotiation, won, or lost at any time.";
    }
    if (currentStage === "negotiation") {
      return "Negotiation is active. Move directly to won, lost, or any earlier step if the process resets.";
    }
    if (currentStage === "won") {
      return "This lead is marked won. You can still move it back to an earlier stage if the deal changes.";
    }
    if (currentStage === "lost") {
      return "Lost leads can be reopened by jumping back to any working stage.";
    }
    return "Pick any target stage below to move this lead immediately.";
  }, [currentStage]);

  const handleStageChange = async (nextStage) => {
    if (!hostRecord?.id) {
      ctx.message?.error?.("Lead record is unavailable.");
      return;
    }

    if (nextStage === currentStage) {
      return;
    }

    setRunningStage(nextStage);
    setMessageText("");
    const optimisticRecord = {
      ...(recordState || hostRecord || {}),
      stage: nextStage,
    };
    setRecordState(optimisticRecord);
    try {
      await updateRecord("leads", hostRecord.id, { stage: nextStage });
      const nextRecord =
        (await loadRecordUntilStage("leads", hostRecord.id, nextStage)) ||
        optimisticRecord;
      setRecordState({
        ...optimisticRecord,
        ...nextRecord,
        stage: nextRecord?.stage || nextStage,
      });
      await refreshBoundResources();
      const nextMeta = stageMeta[nextStage] || { label: nextStage };
      const successText =
        ((nextRecord?.lead_name || hostRecord?.lead_name || "Lead") +
          " moved to " +
          nextMeta.label +
          ".");
      setMessageText(successText);
      ctx.notification?.success?.({
        message: t("Lead updated"),
        description: successText,
      });
    } catch (error) {
      const nextError = error?.message || "Failed to update lead stage.";
      setMessageText(nextError);
      ctx.message?.error?.(nextError);
    } finally {
      setRunningStage("");
    }
  };

  return h(
    Card,
    {
      title: t("Lifecycle actions"),
      style: {
        borderRadius: token.borderRadiusLG,
        border: `1px solid ${token.colorBorderSecondary}`,
        background: `linear-gradient(180deg, ${token.colorBgContainer} 0%, ${token.colorBgElevated} 100%)`,
      },
      extra: h(Tag, { color: currentMeta.color }, currentMeta.label),
    },
    h(
      "div",
      { style: { display: "grid", gap: 14 } },
      h(
        Descriptions,
        { column: 1, size: "small", bordered: true },
        h(
          Descriptions.Item,
          { label: "Lead" },
          recordState?.lead_name || hostRecord?.lead_name || "-"
        ),
        h(Descriptions.Item, { label: t("Current stage") }, currentMeta.label),
        h(
          Descriptions.Item,
          { label: t("How it works") },
          "All stages are listed below in order. The current stage is disabled, and you can jump directly to any other stage."
        )
      ),
      h(
        Paragraph,
        { type: "secondary", style: { marginBottom: 0 } },
        helperText
      ),
      messageText
        ? h(Alert, {
            type:
              messageText.toLowerCase().includes("failed") ||
              messageText.toLowerCase().includes("unavailable")
                ? "error"
                : "success",
            showIcon: true,
            message: messageText,
          })
        : null,
      h(
        Space,
        { wrap: true, size: 8 },
        ...orderedStages.flatMap((stage, index) => {
          const isCurrent = stage.value === currentStage;
          const isBusy = runningStage === stage.value;
          const buttonNode = h(
            Button,
            {
              key: stage.value,
              type: isCurrent || stage.value === "won" ? "primary" : "default",
              danger: stage.value === "lost",
              disabled: isCurrent,
              loading: isBusy,
              style: {
                opacity: 1,
                fontWeight: isCurrent ? 600 : 500,
              },
              onClick: () => handleStageChange(stage.value),
            },
            (index + 1) + ". " + stage.title
          );
          if (index === orderedStages.length - 1) {
            return [buttonNode];
          }
          return [
            buttonNode,
            h(
              "span",
              { key: stage.value + "-arrow", style: arrowStyle },
              "->"
            ),
          ];
        })
      ),
    )
  );
};

ctx.render(h(LeadLifecycleCard));

const t = (k, o) => ctx.t(k, { ns: 'nb_demo', ...(o || {}) });
const React = ctx.libs.React;
const { useMemo, useState } = React;
const dayjs = ctx.libs.dayjs;
const { Button, Card, Empty, List, Space, Tag, Typography, theme } = ctx.libs.antd;
const currentUser = ctx.user ?? ctx.auth?.user ?? null;
const DETAIL_UID = 't7n5cddaxnl';
const APPENDS = ["order"];
const PAGE_SIZE = 6;

function parseDate(value) {
  if (!value) return null;
  const parsed = dayjs(value);
  return parsed.isValid() ? parsed : null;
}

function formatDate(value, format = 'MMM DD, YYYY') {
  const parsed = parseDate(value);
  return parsed ? parsed.format(format) : '-';
}

function titleCase(text) {
  return String(text || '')
    .split('_')
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

function statusColor(value) {
  const key = String(value || '');
  const map = {
    key: 'gold',
    active: 'success',
    prospective: 'processing',
    paused: 'warning',
    lost: 'default',
    new: 'default',
    contacted: 'blue',
    qualified: 'cyan',
    proposal: 'purple',
    negotiation: 'volcano',
    won: 'success',
    draft: 'default',
    sent: 'processing',
    approved: 'success',
    accepted: 'success',
    converted: 'success',
    rejected: 'default',
    pending_assignment: 'default',
    in_progress: 'processing',
    waiting_customer: 'gold',
    waiting_internal: 'purple',
    resolved: 'success',
    closed: 'success',
    cancelled: 'default',
    not_started: 'default',
    planning: 'blue',
    on_hold: 'warning',
    delayed: 'error',
    todo: 'default',
    blocked: 'error',
    idle: 'default',
    assigned: 'processing',
    repair: 'volcano',
    retired: 'default',
    paid: 'success',
    unpaid: 'error',
    partial: 'warning',
    pending: 'warning',
    ready: 'processing',
    completed: 'success',
    resignation: 'volcano',
    termination: 'error',
    transfer: 'blue',
    retirement: 'gold',
    inspection: 'blue',
    repair_service: 'volcano',
    vendor_repair: 'purple',
  };
  return map[key] || 'default';
}

function formatAmount(value, currency) {
  const amount = Number(value || 0);
  if (!Number.isFinite(amount)) return '-';
  if (currency) return currency + ' ' + amount.toLocaleString();
  return amount.toLocaleString();
}

function pushTag(tags, text, color = 'default') {
  if (!text) return;
  tags.push({ text, color });
}

function personName(person) {
  if (!person) return '';
  return person.nickname || person.username || person.full_name || person.employee_no || '';
}

async function loadRows() {
  const resource = ctx.makeResource('MultiRecordResource');
  resource.setResourceName('invoices');
  resource.setPageSize?.(200);
  if (APPENDS.length) {
    resource.setAppends?.(APPENDS);
  }
  await resource.refresh();
  return resource.getData?.() || [];
}

async function openDetails(row) {
  await ctx.openView(DETAIL_UID, {
    filterByTk: row.id,
  });
}

function rowTitle(row) {
  return row.invoice_no || ('#' + row.id);
}

function rowSubtitle(row) {
  return row.order?.order_no || t('Invoice record');
}

function rowTags(row) {
  const tags=[]; pushTag(tags, titleCase(row.invoice_status), statusColor(row.invoice_status)); pushTag(tags, formatAmount(row.invoice_amount)); if (row.invoice_date) pushTag(tags, formatDate(row.invoice_date)); return tags;
}

function includeRow(row) {
  return true;
}

function compareRows(a, b) {
  return dayjs(b.invoice_date || 0).valueOf() - dayjs(a.invoice_date || 0).valueOf();
}

function headerNote(items) {
  return items.length ? t('Latest invoices and their current billing status') : t('No invoices to show.');
}

function PagedListPanel({ items }) {
  // theme.useToken is reactive under antd's ConfigProvider, so the card
  // re-renders automatically when the user switches themes.
  const { token } = theme.useToken();
  const [page, setPage] = useState(1);
  const visibleItems = useMemo(() => items.slice(0, page * PAGE_SIZE), [items, page]);
  const hasMore = visibleItems.length < items.length;

  return (
    <>
      <div style={{ padding: '6px 10px 12px' }}>
        <Space size={12} style={{ justifyContent: 'space-between', width: '100%', alignItems: 'flex-start' }}>
          <div>
            <Typography.Text strong>Invoice overview</Typography.Text>
            <Typography.Text type="secondary" style={{ display: 'block', fontSize: 12, marginTop: 2 }}>
              {headerNote(items)}
            </Typography.Text>
          </div>
          <Tag color="cyan">{items.length}</Tag>
        </Space>
      </div>

      {items.length ? (
        <>
          <List
          dataSource={visibleItems}
          split={false}
          renderItem={(row) => (
            <List.Item style={{ padding: '0 8px 10px' }}>
              <button
                type="button"
                onClick={() => openDetails(row)}
                style={{
                  width: '100%',
                  textAlign: 'left',
                  border: `1px solid ${token.colorBorderSecondary}`,
                  background: token.colorBgContainer,
                  borderRadius: token.borderRadiusLG,
                  padding: '14px 16px',
                  cursor: 'pointer',
                  boxShadow: token.boxShadowCard,
                }}
              >
                <Space size={12} style={{ display: 'flex', justifyContent: 'space-between', width: '100%', alignItems: 'flex-start' }}>
                  <div style={{ minWidth: 0, flex: 1 }}>
                    <Typography.Text strong ellipsis style={{ display: 'block', fontSize: 14 }}>
                      {rowTitle(row)}
                    </Typography.Text>
                    <Typography.Text type="secondary" ellipsis style={{ display: 'block', marginTop: 4, fontSize: 12 }}>
                      {rowSubtitle(row)}
                    </Typography.Text>
                    <Space size={[6, 6]} wrap style={{ marginTop: 10 }}>
                      {rowTags(row).map((tag, index) => (
                        <Tag key={index} color={tag.color || 'default'}>{tag.text}</Tag>
                      ))}
                    </Space>
                  </div>
                  <Button type="link" size="small" onClick={(event) => { event.stopPropagation(); openDetails(row); }}>
                    {t('View')}
                  </Button>
                </Space>
              </button>
            </List.Item>
          )}
        />
          {hasMore ? (
            <div style={{ padding: '0 8px 10px' }}>
              <Button block onClick={() => setPage((current) => current + 1)}>
                {t('Load more')}
              </Button>
            </div>
          ) : null}
        </>
      ) : (
        <div style={{ padding: '18px 8px 10px' }}>
          <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description={t('No invoices')} />
        </div>
      )}
    </>
  );
}

try {
  const rows = await loadRows();
  const items = rows
    .filter((row) => includeRow(row))
    .sort(compareRows);

  ctx.render(<PagedListPanel items={items} />);
} catch (error) {
  ctx.render(
    <div style={{ padding: 12 }}>
        <Typography.Text type="secondary">{t('Invoice overview is temporarily unavailable.')}</Typography.Text>
      </div>
  );
}

